#[utoipa::path(get,path="/v1/deliveries/{id}",params(("id"=String,Path,description="Delivery uses its opaque order reference")),responses((status=200,body=Object),(status=404,body=ErrorBody)),security(("bearer"=[])))]
async fn delivery(
