pub(crate) fn location(digest: &str, node: u32) -> Value {
    let (latitude, longitude) = match node {
        0 => (0.0, 0.0),
        1 => (0.0, 0.001),
        2 => (0.0, 0.002),
        _ => (0.001, 0.002),
    };
