//! Machine-readable route corpus export for reference-engine validation.

use std::collections::BTreeMap;

use roadrunner_core::cost::{RoutingContext, TravelTimeCost};
use roadrunner_core::graph::{FrozenGraph, NodeId, Orientation};
use roadrunner_core::routing::{RoutingError, dijkstra};
use roadrunner_osm::load_snapshot_bundle;
use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Corpus {
    schema_version: u32,
    fixture: String,
    queries: Vec<Query>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Query {
    id: String,
    from_osm_node: i64,
    to_osm_node: i64,
    expected: String,
}

#[derive(Serialize)]
struct Export {
    schema_version: u32,
    fixture: String,
    graph_snapshot_digest: String,
    source_sha256: String,
    routing_profile: String,
    graph_node_count: usize,
    graph_edge_count: usize,
    queries: Vec<ExportQuery>,
}

#[derive(Serialize)]
struct ExportQuery {
    id: String,
    from_osm_node: i64,
    to_osm_node: i64,
    origin: [f64; 2],
    destination: [f64; 2],
    expected_status: String,
    status: &'static str,
    distance_meters: Option<f64>,
    duration_seconds: Option<f64>,
    geometry: Option<Vec<[f64; 2]>>,
}

pub(super) fn run(snapshot: &str, corpus_path: &str) -> Result<(), String> {
    let loaded = load_snapshot_bundle(snapshot, true).map_err(|error| error.to_string())?;
    let corpus_bytes = std::fs::read(corpus_path)
        .map_err(|error| format!("could not read route corpus {corpus_path}: {error}"))?;
    let corpus: Corpus =
        serde_json::from_slice(&corpus_bytes).map_err(|error| error.to_string())?;
    if corpus.schema_version != 1 || corpus.queries.is_empty() {
        return Err("route corpus must contain schema version 1 and queries".to_owned());
    }
    let source_nodes: BTreeMap<_, _> = loaded
        .provenance
        .nodes
        .iter()
        .map(|entry| (entry.osm_node_id, NodeId::new(entry.node_id)))
        .collect();
    let mut output = Vec::with_capacity(corpus.queries.len());
    for query in corpus.queries {
        if !matches!(query.expected.as_str(), "reachable" | "unreachable") {
            return Err(format!("invalid expectation for query {}", query.id));
        }
        let source = source_nodes
            .get(&query.from_osm_node)
            .ok_or_else(|| format!("query {} origin is absent from graph provenance", query.id))?;
        let destination = source_nodes.get(&query.to_osm_node).ok_or_else(|| {
            format!(
                "query {} destination is absent from graph provenance",
                query.id
            )
        })?;
        let origin = coordinate(&loaded.graph, *source)?;
        let destination_coordinate = coordinate(&loaded.graph, *destination)?;
        let (status, distance_meters, duration_seconds, geometry) = match dijkstra(
            &loaded.graph,
            *source,
            *destination,
            &TravelTimeCost,
            &RoutingContext::new(),
        ) {
            Ok(route) => (
                "reachable",
                Some(route.total_distance().value()),
                Some(route.elapsed_travel_time().value()),
                Some(route_geometry(&loaded.graph, route.edges(), origin)?),
            ),
            Err(RoutingError::NoRoute { .. }) => ("unreachable", None, None, None),
            Err(error) => return Err(format!("query {} failed: {error}", query.id)),
        };
        output.push(ExportQuery {
            id: query.id,
            from_osm_node: query.from_osm_node,
            to_osm_node: query.to_osm_node,
            origin,
            destination: destination_coordinate,
            expected_status: query.expected,
            status,
            distance_meters,
            duration_seconds,
            geometry,
        });
    }
    let export = Export {
        schema_version: 1,
        fixture: corpus.fixture,
        graph_snapshot_digest: loaded.manifest.graph_snapshot_digest,
        source_sha256: loaded.manifest.source_pbf_sha256,
        routing_profile: loaded.manifest.routing_profile,
        graph_node_count: loaded.graph.node_count(),
        graph_edge_count: loaded.graph.edge_count(),
        queries: output,
    };
    println!(
        "{}",
        serde_json::to_string(&export).map_err(|error| error.to_string())?
    );
    Ok(())
}

fn coordinate(graph: &FrozenGraph, node_id: NodeId) -> Result<[f64; 2], String> {
    let node = graph
        .node(node_id)
        .ok_or_else(|| format!("node {node_id} is missing"))?;
    let coordinate = node.coordinate();
    Ok([coordinate.longitude(), coordinate.latitude()])
}

fn route_geometry(
    graph: &FrozenGraph,
    edges: &[roadrunner_core::graph::EdgeId],
    origin: [f64; 2],
) -> Result<Vec<[f64; 2]>, String> {
    let mut line = Vec::new();
    for edge_id in edges {
        let edge = graph
            .edge(*edge_id)
            .ok_or_else(|| format!("edge {edge_id} is missing"))?;
        let geometry = graph
            .segment_geometry(edge.segment())
            .map_err(|error| error.to_string())?;
        let coordinates = geometry.iter().map(|point| {
            let point = point.to_coordinate();
            [point.longitude(), point.latitude()]
        });
        match edge.orientation() {
            Orientation::Forward => line.extend(coordinates.skip(usize::from(!line.is_empty()))),
            Orientation::Reverse => {
                line.extend(coordinates.rev().skip(usize::from(!line.is_empty())));
            }
        }
    }
    if line.is_empty() {
        line.push(origin);
    }
    Ok(line)
}

crates/roadrunner-cli/src/simulation_com.utf8:
//! Versioned scenario loading and composition over the deterministic simulation library.

use std::collections::BTreeMap;
use std::path::Path;

use roadrunner_core::geo::{CanonicalCoordinate, KilometersPerHour};
use roadrunner_core::graph::{
    AccessClass, BuilderNodeId, BuilderSegmentId, EdgeProperties, FrozenGraph, GraphBuildIdentity,
    GraphBuilder, GraphMetadata, GraphSnapshotId, decode_graph_artifact,
};
use roadrunner_simulation::{SimulationScenario, compare_strategies, simulate};
use serde::Deserialize;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Document {
    graph: GraphSource,
    scenario: SimulationScenario,
}

#[derive(Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
enum GraphSource {
    Inline {
        profile: String,
        nodes: Vec<NodeInput>,
        roads: Vec<RoadInput>,
    },
    Artifact {
        path: String,
    },
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct NodeInput {
    id: u64,
    coordinate: CoordinateInput,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RoadInput {
    id: u64,
    from: u64,
    to: u64,
    speed_kph: KilometersPerHour,
    bidirectional: bool,
    #[serde(default)]
    geometry: Option<Vec<CoordinateInput>>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct CoordinateInput {
    latitude_e7: i32,
    longitude_e7: i32,
}

impl CoordinateInput {
    fn canonical(&self) -> Result<CanonicalCoordinate, String> {
        CanonicalCoordinate::new(self.latitude_e7, self.longitude_e7).map_err(|e| e.to_string())
    }
}

fn inline_graph(
    profile: &str,
    nodes: &[NodeInput],
    roads: &[RoadInput],
) -> Result<FrozenGraph, String> {
    if profile.is_empty() {
        return Err("inline graph profile must not be empty".into());
    }
    let coordinates: BTreeMap<_, _> = nodes
        .iter()
        .map(|n| Ok((n.id, n.coordinate.canonical()?)))
        .collect::<Result<_, String>>()?;
    if coordinates.len() != nodes.len() {
        return Err("duplicate inline node identity".into());
    }
    let mut builder = GraphBuilder::new(
        GraphSnapshotId::new(15),
        GraphMetadata::new(
            profile,
            "synthetic scenario",
            GraphBuildIdentity::new("simulation-inline", "v1", "v1", "synthetic"),
        ),
    );
    for (index, (&id, &coordinate)) in coordinates.iter().enumerate() {
        if u64::try_from(index).map_err(|e| e.to_string())? != id {
            return Err("inline node IDs must be contiguous from zero".into());
        }
        builder
            .add_node(BuilderNodeId::new(id), coordinate)
            .map_err(|e| e.to_string())?;
    }
    for road in roads {
        let from = coordinates.get(&road.from).ok_or("absent road origin")?;
        let to = coordinates.get(&road.to).ok_or("absent road destination")?;
        let properties = EdgeProperties::new(road.speed_kph, None, AccessClass::General);
        builder
            .add_segment(
                BuilderSegmentId::new(road.id),
                BuilderNodeId::new(road.from),
                BuilderNodeId::new(road.to),
                road.geometry
                    .as_ref()
                    .map(|points| {
                        points
                            .iter()
                            .map(CoordinateInput::canonical)
                            .collect::<Result<Vec<_>, _>>()
                    })
                    .transpose()?
                    .unwrap_or_else(|| vec![*from, *to]),
                Some(properties),
                road.bidirectional.then_some(properties),
            )
            .map_err(|e| e.to_string())?;
    }
    builder.finalize().map_err(|e| e.to_string())
}

pub(super) fn load(path: &str) -> Result<(FrozenGraph, SimulationScenario), String> {
    let bytes = std::fs::read(path).map_err(|e| format!("could not read scenario {path}: {e}"))?;
    let document: Document = serde_json::from_slice(&bytes).map_err(|e| e.to_string())?;
    let graph = match document.graph {
        GraphSource::Inline {
            profile,
            nodes,
            roads,
        } => inline_graph(&profile, &nodes, &roads)?,
        GraphSource::Artifact { path: artifact } => {
            if document.scenario.graph_snapshot_digest.is_none() {
                return Err("artifact scenarios must bind graph_snapshot_digest".into());
            }
            let artifact = Path::new(path)
                .parent()
                .unwrap_or_else(|| Path::new("."))
                .join(artifact);
            decode_graph_artifact(&std::fs::read(&artifact).map_err(|e| {
                format!("could not read graph artifact {}: {e}", artifact.display())
            })?)
            .map_err(|e| e.to_string())?
        }
    };
    Ok((graph, document.scenario))
}

pub(super) fn compare_arguments(path: &str, arguments: &[String]) -> Result<(), String> {
    let mut json = false;
    let mut weight = 1.0;
    let mut args = arguments.iter();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--json" if !json => json = true,
            "--idle-penalty-weight" => {
                weight = args
                    .next()
                    .ok_or("missing idle penalty weight")?
                    .parse::<f64>()
                    .map_err(|e| e.to_string())?;
            }
            _ => return Err(format!("unknown comparison argument: {arg}")),
        }
    }
    compare(path, json, weight)
}

pub(super) fn compare(path: &str, json: bool, weight: f64) -> Result<(), String> {
    let (graph, scenario) = load(path)?;
    let result = compare_strategies(&graph, &scenario, weight).map_err(|e| e.to_string())?;
    if json {
        println!(
            "{}",
            serde_json::to_string_pretty(&result).map_err(|e| e.to_string())?
        );
    } else {
        for run in &result.runs {
            println!("\nStrategy: {:?}", run.dispatch);
            print_summary(run);
        }
    }
    Ok(())
}

pub(super) fn run(path: &str, json: bool) -> Result<(), String> {
    let (graph, scenario) = load(path)?;
    let result = simulate(&graph, &scenario).map_err(|e| e.to_string())?;
    if json {
        println!(
            "{}",
            serde_json::to_string_pretty(&result).map_err(|e| e.to_string())?
        );
    } else {
        print_summary(&result);
    }
    Ok(())
}

fn print_summary(result: &roadrunner_simulation::SimulationResult) {
    for failure in &result.prediction_failures {
        println!(
            "Insertion order {}: PredictionUnavailable for order {}; inputs_complete=false; committed=false",
            failure.order.value(),
            failure.unavailable_order.value()
        );
    }
    for record in &result.insertions {
        let evidence = record.decision.evidence();
        println!(
            "Insertion order {}: {:?}; committed={}; inputs_complete={}; riders_complete={}; search_complete={}; work={}",
            evidence.order.value(),
            evidence.termination,
            record.committed,
            evidence.input_complete,
            evidence.riders_complete,
            evidence.search_complete,
            evidence.work
        );
        if let Some(proposal) = record.decision.proposal() {
            println!(
                "  rider {}: incremental road {:.3} s, {:.3} m; plan {:?}",
                proposal.rider().value(),
                proposal.incremental_travel(),
                proposal.incremental_distance(),
                proposal.evaluation().plan.stops
            );
        }
        for rider in &evidence.riders {
            println!(
                "  rider {}: suffix={}, pairs={}, evaluated={}, excluded={}, feasible={}, breaches={:?}, rejected={:?}",
                rider.rider.value(),
                rider.suffix_length,
                rider.pairs_total,
                rider.evaluated,
                rider.pruned,
                rider.feasible,
                rider.baseline.breaches,
                rider.rejections
            );
        }
    }
    print_fleets(result);
    print_recoveries(result);
    if let Some(basis) = &result.utilization_basis {
        println!("Utilization basis: {basis}");
    }
    if result.summary.cancelled_orders > 0 {
        println!("Cancelled: {}", result.summary.cancelled_orders);
    }
    let s = &result.summary;
    println!(
        "Orders: {} (scheduled: {}, uncreated: {})\nAssigned: {}\nDelivered: {}\nUnassigned: {}\nAssigned unfinished: {}\nLate deliveries: {}\nOutstanding past deadline: {}",
        s.created_orders,
        s.scheduled_orders,
        s.uncreated_orders,
        s.assigned_orders,
        s.delivered_orders,
        s.unassigned_orders,
        s.assigned_unfinished_orders,
        s.late_deliveries,
        s.outstanding_past_deadline
    );
    let duration = |v: Option<roadrunner_core::geo::Seconds>| {
        v.map_or_else(|| "unavailable".into(), |v| format!("{:.3} s", v.value()))
    };
    println!(
        "Median predicted ETA: {}\np95 predicted ETA: {}\nMean delivered duration: {}\nMedian delivered duration: {}\np95 delivered duration: {}\nMean pickup wait: {}\nMean rider idle time: {}\nRider utilization: {}\nCompleted distance: {:.3} m\nWindow: {}..{} s\nSeed: {}",
        duration(s.predicted_eta.median_seconds),
        duration(s.predicted_eta.p95_seconds),
        duration(s.delivered_duration.mean_seconds),
        duration(s.delivered_duration.median_seconds),
        duration(s.delivered_duration.p95_seconds),
        duration(s.pickup_waiting.mean_seconds),
        duration(s.mean_rider_idle_seconds),
        s.rider_utilization
            .map_or_else(|| "unavailable".into(), |v| format!("{:.3}%", v * 100.0)),
        s.completed_distance_meters.value(),
        result.started_at.value(),
        result.ended_at.value(),
        result.seed
    );
}

fn print_recoveries(result: &roadrunner_simulation::SimulationResult) {
    for record in &result.recoveries {
        if let Some(d) = &record.decision {
            println!(
                "Recovery {}: {:?}; committed: {}; work: {}/{}; repair required: {}",
                d.evidence().context.trigger,
                d.evidence().termination,
                record.committed,
                d.evidence().evaluated,
                d.evidence().context.pooling.inputs.work_budget,
                d.evidence().baseline_requires_repair
            );
            if let Some(p) = d.proposal() {
                println!(
                    "  Remaining road: {:.3} s / {:.3} m; churn penalty: {:.3} s",
                    p.travel_seconds, p.distance_meters, p.penalty_seconds
                );
            }
        } else {
            println!(
                "Recovery failed: {}",
                record.failure.as_deref().unwrap_or("unknown")
            );
        }
    }
}

fn print_fleets(result: &roadrunner_simulation::SimulationResult) {
    for record in &result.fleets {
        let e = record.decision.evidence();
        println!(
            "Fleet batch {:?}: {:?}; committed={}; inputs_complete={}; riders_complete={}; search_complete={}; work={}",
            e.batch,
            e.termination,
            record.committed,
            e.input_complete,
            e.riders_complete,
            e.search_complete,
            e.work.total()
        );
        if let Some(objective) = &e.selected_objective {
            println!(
                "  admitted={}; remaining road={:.3} s, {:.3} m",
                objective.admitted_orders, objective.road_seconds, objective.road_meters
            );
        }
        for rider in &e.riders {
            println!(
                "  rider {}: isolation={:?}; suffix={}; plan={:?}",
                rider.rider.value(),
                rider.isolation,
                rider.suffix_length,
                rider.selected.as_ref().map(|p| &p.plan.stops)
            );
        }
    }
}

