#[test]
fn phase17_pooled_cli_replays_success_rejections_and_prediction_failure() {
    let root =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../data/fixtures/phase-17");
    for name in [
        "successful-pooling",
        "capacity-prefix",
        "complete-infeasibility",
        "hard-deadline",
