use thiserror::Error;

use crate::cost::{CostError, CostKind, HeuristicPolicy, SearchCapability};
use crate::geo::UnitError;
use crate::graph::{EdgeId, GraphError, NodeId};

/// Identifies an invalid route endpoint.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RouteEndpoint {
    /// Route origin.
    Source,
    /// Route destination.
    Destination,
}

impl std::fmt::Display for RouteEndpoint {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(match self {
            Self::Source => "source",
            Self::Destination => "destination",
        })
    }
}

/// Errors produced while calculating or reconstructing a route.
#[derive(Debug, Clone, PartialEq, Error)]
pub enum RoutingError {
    /// The selected evaluator is bound to a different graph snapshot.
    #[error("traversal evaluator belongs to a different graph snapshot")]
    EvaluatorGraphMismatch,
    /// Alternative-route options violate their required bounds.
    #[error("invalid alternative-route options: {reason}")]
    InvalidAlternativeOptions {
        /// Description of the invalid value.
        reason: &'static str,
    },
    /// The bounded search could not establish an initial shortest route.
    #[error("alternative-route search exhausted its state budget before finding a primary route")]
    AlternativeSearchLimit,
    /// A requested endpoint is absent.
    #[error("{endpoint} node {node_id} does not exist")]
    NodeNotFound {
        /// Endpoint role.
        endpoint: RouteEndpoint,
        /// Missing node.
        node_id: NodeId,
    },
    /// No permitted path connects valid endpoints.
    #[error("no route from node {source_node} to node {destination}")]
    NoRoute {
        /// Valid origin.
        source_node: NodeId,
        /// Valid destination.
        destination: NodeId,
    },
    /// Graph lookup failed.
    #[error("graph query failed: {source}")]
    Graph {
        /// Underlying graph error.
        #[source]
        source: GraphError,
    },
    /// Traversal evaluation failed.
    #[error("traversal evaluation failed for edge {edge_id}: {source}")]
    TraversalEvaluation {
        /// Edge being evaluated.
        edge_id: EdgeId,
        /// Underlying evaluator error.
        #[source]
        source: CostError,
    },
    /// An evaluator produced the wrong objective kind.
    #[error("edge {edge_id} returned {actual} cost; expected {expected}")]
    CostKindMismatch {
        /// Edge producing the mismatch.
        edge_id: EdgeId,
        /// Evaluator's declared kind.
        expected: CostKind,
        /// Returned kind.
        actual: CostKind,
    },
    /// A node-state algorithm cannot serve the requested capability.
    #[error("routing algorithm does not support evaluator capability {capability:?}")]
    UnsupportedCapability {
        /// Unsupported requirement.
        capability: SearchCapability,
    },
    /// Heuristic and evaluator objective kinds differ.
    #[error("heuristic produces {heuristic}; evaluator produces {evaluator}")]
    HeuristicKindMismatch {
        /// Heuristic objective kind.
        heuristic: CostKind,
        /// Evaluator objective kind.
        evaluator: CostKind,
    },
    /// The heuristic does not support the evaluator capability.
    #[error("heuristic is incompatible with evaluator capability {capability:?}")]
    HeuristicCapabilityMismatch {
        /// Unsupported evaluator capability.
        capability: SearchCapability,
    },
    /// The evaluator has not proved compatibility with the selected heuristic policy.
    #[error("evaluator is incompatible with heuristic policy {policy:?}")]
    HeuristicPolicyMismatch {
        /// Rejected policy.
        policy: HeuristicPolicy,
    },
    /// Prevalidated heuristic parameters belong to another graph snapshot.
    #[error("heuristic parameters were validated for a different graph snapshot")]
    HeuristicGraphMismatch,
    /// FIFO earliest-arrival evaluation did not use travel time as objective.
    #[error("FIFO edge {edge_id} objective must equal its travel time")]
    FifoObjectiveMismatch {
        /// Invalid FIFO edge.
        edge_id: EdgeId,
    },
    /// Objective accumulation failed.
    #[error("objective accumulation failed at edge {edge_id}: {source}")]
    CostAccumulation {
        /// Edge whose objective overflowed.
        edge_id: EdgeId,
        /// Underlying cost error.
        #[source]
        source: CostError,
    },
    /// Elapsed-time accumulation failed.
    #[error("elapsed-time accumulation failed at edge {edge_id}: {source}")]
    TimeAccumulation {
        /// Edge whose elapsed time overflowed.
        edge_id: EdgeId,
        /// Underlying unit error.
        #[source]
        source: UnitError,
    },
    /// Heuristic evaluation failed.
    #[error("heuristic evaluation failed for node {node_id}: {source}")]
    HeuristicEvaluation {
        /// Node being estimated.
        node_id: NodeId,
        /// Underlying cost error.
        #[source]
        source: CostError,
    },
    /// Combining path and heuristic costs failed.
    #[error("estimated-total calculation failed for node {node_id}: {source}")]
    EstimatedTotal {
        /// Node whose total failed.
        node_id: NodeId,
        /// Underlying cost error.
        #[source]
        source: CostError,
    },
    /// Physical distance accumulation failed.
    #[error("distance accumulation failed at edge {edge_id}: {source}")]
    DistanceAccumulation {
        /// Edge whose distance overflowed.
        edge_id: EdgeId,
        /// Underlying unit error.
        #[source]
        source: UnitError,
    },
    /// A predecessor is absent.
    #[error("route predecessor is missing for node {node_id}")]
    MissingPredecessor {
        /// Node without a predecessor.
        node_id: NodeId,
    },
    /// A predecessor edge is absent.
    #[error("route predecessor edge {edge_id} is missing")]
    MissingRouteEdge {
        /// Missing edge.
        edge_id: EdgeId,
    },
    /// A predecessor does not lead to the expected node.
    #[error("predecessor edge {edge_id} leads to {actual_to}; expected {expected_to}")]
    InvalidPredecessorEdge {
        /// Invalid edge.
        edge_id: EdgeId,
        /// Expected edge target.
        expected_to: NodeId,
        /// Actual edge target.
        actual_to: NodeId,
    },
    /// The predecessor chain contains a cycle.
    #[error("route predecessor chain contains a cycle")]
    PredecessorCycle,
}

crates/roadrunner-core/src/routing/heuri.utf8:
use thiserror::Error;

use crate::cost::{CostError, CostKind, HeuristicPolicy, RouteCost, SearchCapability};
use crate::geo::{KilometersPerHour, haversine_distance};
use crate::graph::{FrozenGraph, GraphSnapshotId, NodeId};

const NUMERICAL_LOWER_BOUND_FACTOR: f64 = 1.0 - 1.0e-9;

fn conservative_lower_bound(value: f64) -> f64 {
    if value == 0.0 {
        return 0.0;
    }
    value * NUMERICAL_LOWER_BOUND_FACTOR
}

/// Lower-bound policy used by A*.
pub trait Heuristic: Send + Sync {
    /// Returns the objective kind estimated by this heuristic.
    fn kind(&self) -> CostKind;
    /// Returns the named policy whose proof contract this implementation uses.
    fn policy(&self) -> HeuristicPolicy;
    /// Returns the graph snapshot to which prevalidated parameters are bound.
    fn graph_snapshot_id(&self) -> Option<GraphSnapshotId> {
        None
    }
    /// Returns whether the heuristic is proved for a search capability.
    fn supports(&self, capability: SearchCapability) -> bool;
    /// Estimates remaining objective cost.
    ///
    /// # Errors
    ///
    /// Returns an error when the estimate cannot be represented.
    fn estimate(
        &self,
        graph: &FrozenGraph,
        node: NodeId,
        destination: NodeId,
    ) -> Result<RouteCost, CostError>;
}

/// Conservative heuristic that always returns zero.
#[derive(Debug, Clone, Copy)]
pub struct ZeroHeuristic {
    kind: CostKind,
}

impl ZeroHeuristic {
    /// Creates a zero heuristic for an objective kind.
    #[must_use]
    pub const fn new(kind: CostKind) -> Self {
        Self { kind }
    }
}

impl Heuristic for ZeroHeuristic {
    fn kind(&self) -> CostKind {
        self.kind
    }
    fn policy(&self) -> HeuristicPolicy {
        HeuristicPolicy::Zero
    }
    fn supports(&self, capability: SearchCapability) -> bool {
        matches!(
            capability,
            SearchCapability::StaticNonNegative | SearchCapability::FifoEarliestArrival
        )
    }
    fn estimate(
        &self,
        _graph: &FrozenGraph,
        _node: NodeId,
        _destination: NodeId,
    ) -> Result<RouteCost, CostError> {
        Ok(RouteCost::zero(self.kind))
    }
}

/// Haversine lower bound for physical-distance routing.
#[derive(Debug, Default, Clone, Copy)]
pub struct DistanceHaversine;

impl Heuristic for DistanceHaversine {
    fn kind(&self) -> CostKind {
        CostKind::Distance
    }
    fn policy(&self) -> HeuristicPolicy {
        HeuristicPolicy::DistanceHaversine
    }
    fn supports(&self, capability: SearchCapability) -> bool {
        capability == SearchCapability::StaticNonNegative
    }
    fn estimate(
        &self,
        graph: &FrozenGraph,
        node: NodeId,
        destination: NodeId,
    ) -> Result<RouteCost, CostError> {
        let from = graph
            .node(node)
            .map_or(crate::geo::Coordinate::ORIGIN, |value| value.coordinate());
        let to = graph
            .node(destination)
            .map_or(crate::geo::Coordinate::ORIGIN, |value| value.coordinate());
        RouteCost::new(
            CostKind::Distance,
            conservative_lower_bound(haversine_distance(from, to).value()),
        )
    }
}

/// Haversine travel-time lower bound using a proven maximum profile speed.
#[derive(Debug, Clone, Copy)]
pub struct TravelTimeHaversine {
    maximum_speed: KilometersPerHour,
    graph_snapshot_id: GraphSnapshotId,
}

impl TravelTimeHaversine {
    /// Creates a travel-time heuristic from a positive maximum possible speed.
    ///
    /// # Errors
    ///
    /// Returns an error for a zero speed.
    pub fn for_graph(
        graph: &FrozenGraph,
        maximum_speed: KilometersPerHour,
    ) -> Result<Self, HeuristicConfigError> {
        if maximum_speed.value() == 0.0 {
            return Err(HeuristicConfigError::ZeroMaximumSpeed);
        }
        let observed_maximum = graph
            .edges()
            .iter()
            .map(|edge| edge.properties().effective_free_flow_speed().value())
            .fold(0.0_f64, f64::max);
        if maximum_speed.value() < observed_maximum {
            return Err(HeuristicConfigError::SpeedBoundTooLow {
                configured_kph: maximum_speed.value(),
                observed_kph: observed_maximum,
            });
        }
        Ok(Self {
            maximum_speed,
            graph_snapshot_id: graph.snapshot_id(),
        })
    }
}

impl Heuristic for TravelTimeHaversine {
    fn kind(&self) -> CostKind {
        CostKind::TravelTime
    }
    fn policy(&self) -> HeuristicPolicy {
        HeuristicPolicy::TravelTimeHaversine
    }
    fn graph_snapshot_id(&self) -> Option<GraphSnapshotId> {
        Some(self.graph_snapshot_id)
    }
    fn supports(&self, capability: SearchCapability) -> bool {
        matches!(
            capability,
            SearchCapability::StaticNonNegative | SearchCapability::FifoEarliestArrival
        )
    }
    fn estimate(
        &self,
        graph: &FrozenGraph,
        node: NodeId,
        destination: NodeId,
    ) -> Result<RouteCost, CostError> {
        let from = graph
            .node(node)
            .map_or(crate::geo::Coordinate::ORIGIN, |value| value.coordinate());
        let to = graph
            .node(destination)
            .map_or(crate::geo::Coordinate::ORIGIN, |value| value.coordinate());
        let seconds = haversine_distance(from, to).value() / (self.maximum_speed.value() / 3.6);
        RouteCost::new(CostKind::TravelTime, conservative_lower_bound(seconds))
    }
}

/// Invalid immutable heuristic configuration.
#[derive(Debug, Clone, Copy, PartialEq, Error)]
pub enum HeuristicConfigError {
    /// Maximum possible speed must be positive.
    #[error("maximum possible speed must be greater than zero")]
    ZeroMaximumSpeed,
    /// Configured bound is lower than an edge's compiled free-flow speed.
    #[error(
        "maximum speed {configured_kph} km/h is below observed graph speed {observed_kph} km/h"
    )]
    SpeedBoundTooLow {
        /// Rejected configured upper bound.
        configured_kph: f64,
        /// Largest compiled edge speed.
        observed_kph: f64,
    },
}

