    );
    assert!(matches!(
        invalid,
        Err(RoutingError::InvalidAlternativeOptions { .. })
    ));

    let weighted = WeightedEvaluator {
        weights: BTreeMap::from([
            (edge_between(&network, 0, 2), 1.0),
            (edge_between(&network, 0, 1), 1.0),
