    }
    let graph = graph(node_count, &segments);
    for (source, destination) in [(0, 999), (13, 23), (0, 500)] {
        let dijkstra_route = dijkstra(
            &graph,
            NodeId::new(source),
            NodeId::new(destination),
            &DistanceCost,
            &RoutingContext::new(),
        );
