/// Constructs all logical components after source replay/authority reconciliation.
/// # Errors
/// Rejects source, graph, split, provenance or reproducibility contract failures.
pub fn build_dataset(
    mut sources: Vec<SourceCapture>,
    version: &str,
    reproduction: Reproduction,
    request: SplitRequest,
) -> Result<DatasetBundle, DatasetError> {
    if sources.is_empty() || version.is_empty() {
        return Err(DatasetError::Source(
            "empty dataset/source population".into(),
        ));
    }
    for name in [
        "Cargo.toml",
        "Cargo.lock",
        "rust-toolchain.toml",
        "crates/roadrunner-dataset/src/lib.rs",
    ] {
        if !reproduction.files.contains_key(name) {
            return Err(DatasetError::Source(format!(
                "missing reproduction bytes: {name}"
            )));
        }
    }
    if reproduction.base_revision.is_empty() || reproduction.toolchain.is_empty() {
        return Err(DatasetError::Source(
            "missing code/toolchain identity".into(),
        ));
    }
    for bytes in reproduction.files.values() {
        bytes.verify()?;
    }
    reproduction.patch.verify()?;
    sources.sort_by(|a, b| a.run.cmp(&b.run));
    let splits = plan_splits(&sources, request)?;
    let mut rows = Vec::new();
    for source in &sources {
        rows.extend(source_rows(source, &splits)?);
    }
    let quality = quality_report(&rows, &sources, &splits)?;
    let evaluation = evaluation_package(&splits);
    Ok(DatasetBundle {
        schema: "eta-dataset/v1; sorted-json-keys; binary64-roundtrip; lossless-u64".into(),
        dataset_version: version.into(),
        sources,
        reproduction,
        rows,
        splits,
        quality,
        evaluation,
    })
}

fn source_rows(
    source: &SourceCapture,
    splits: &SplitPlan,
) -> Result<Vec<DatasetRow>, DatasetError> {
    let mut rows = Vec::new();
    let (graph, trace) = source.verify()?;
    let content = source.content_id()?;
    for start in &trace.starts {
        let effects: Vec<_> = trace
            .effects
            .iter()
            .filter(|e| {
                e.action == start.original.action_id && e.effect == ExecutionEffect::Arrival
            })
            .collect();
        let endpoint = effects.first().map(|e| e.at);
        let label = assess_label(LabelEvidence {
            start_effective_at: start.original.route.departed_at,
            arrival_reported_at: endpoint,
            arrival_processing_sample_at: trace
                .arrivals
                .iter()
                .find(|a| a.action == start.original.action_id)
                .map(|a| a.processing_sample_at),
            boundary: trace.horizon,
            non_arrival_through: endpoint.is_none().then_some(trace.horizon),
            source_closed: true,
            disputed: false,
            clock: ClockWitness::SyntheticLogicalV1,
            measurement: MeasurementSupport::SyntheticControlled,
        });
        let features = extract_features(start, Some(&graph))?;
        let mut provenance = BTreeMap::new();
        for (name, meaning) in [
            ("start", RecordMeaning::CommittedDomainFact),
            ("b0", RecordMeaning::RoutingEstimate),
            ("features", RecordMeaning::DerivedValue),
            ("label", RecordMeaning::DerivedValue),
        ] {
            provenance.insert(
                name.into(),
                Provenance {
                    producer_origin: ProducerOrigin::Simulator,
                    record_meaning: meaning,
                    measurement_support: MeasurementSupport::SyntheticControlled,
                    derivation_lineage: vec![
                        format!("source:{content}"),
                        format!("action:{}", start.original.action_id.value()),
                        format!("start-revision:{}", start.committed_revision.number),
                        format!("{name}/v1"),
                    ],
                },
            );
        }
        rows.push(DatasetRow {
            key: ActionKey {
                run: source.run.clone(),
                namespace: trace.final_revision.namespace,
                action: start.original.action_id,
            },
            rider: start.rider,
            features,
            label,
            provenance,
            source_content: content.clone(),
            arrival_effects: effects.iter().map(|e| e.id).collect(),
            dependency_group: splits.groups[&source.run].clone(),
            partition: splits.request.assignments[&source.run],
        });
    }

    Ok(rows)
}
fn quality_report(
    rows: &[DatasetRow],
    sources: &[SourceCapture],
    splits: &SplitPlan,
) -> Result<QualityReport, DatasetError> {
    let mut quality = QualityReport {
        committed_starts: rows.len(),
        outcomes: [
            Lifecycle::Observed,
            Lifecycle::Pending,
            Lifecycle::RightCensored,
            Lifecycle::MissingArrival,
            Lifecycle::DisputedOrInvalid,
        ]
        .into_iter()
        .map(|s| (s, 0))
        .collect(),
        exact_labels: 0,
        excluded_rows: 0,
        unavailable_features: BTreeMap::new(),
        policy_coverage: BTreeMap::new(),
        b0_predictions: rows.len(),
        dependency_groups: splits.groups.values().collect::<BTreeSet<_>>().len(),
        reasons: BTreeMap::new(),
        distance_band_coverage: BTreeMap::new(),
        source_coverage: BTreeMap::new(),
        cohort: MeasurementSupport::SyntheticControlled,
    };
    for row in rows {
        quality.excluded_rows += usize::from(row.partition == Partition::Excluded);
        for field in [
            "road_class:UnsupportedSemantics",
            "day_of_week:NotApplicable",
        ] {
            *quality
                .unavailable_features
                .entry(field.into())
                .or_default() += 1;
        }
        let policy = sources
            .iter()
            .find(|s| s.run == row.key.run)
            .map(|s| s.lineage.policy.clone())
            .ok_or_else(|| DatasetError::Integrity("source lineage join".into()))?;
        let counts = quality.policy_coverage.entry(policy).or_default();
        counts.0 += 1;
        counts.1 += usize::from(row.label.duration_seconds.is_some());
        *quality.outcomes.entry(row.label.outcome).or_default() += 1;
        let eligible = usize::from(row.label.duration_seconds.is_some());
        quality.exact_labels += eligible;
        for reason in &row.label.reasons {
            *quality.reasons.entry(reason.clone()).or_default() += 1;
        }
        let distance = row.features.distance_meters.value();
        let band = if distance < 1000.0 {
            "under_1km"
        } else if distance < 5000.0 {
            "1_to_5km"
        } else {
            "at_least_5km"
        };
        let counts = quality
            .distance_band_coverage
            .entry(band.into())
            .or_default();
        counts.0 += 1;
        counts.1 += eligible;
        let counts = quality
            .source_coverage
            .entry(row.key.run.clone())
            .or_default();
        counts.0 += 1;
        counts.1 += eligible;
    }
    Ok(quality)
}
fn evaluation_package(splits: &SplitPlan) -> EvaluationPackage {
    EvaluationPackage {
        target: "started whole-road-leg: synthetic accepted arrival minus logical start; predictor reference=start_effective_at".into(),
        rules: vec!["B0=original frozen route travel seconds; never updated".into(), "immutable-as-of/v1; no corrections overwrite prior versions".into(),
            "equal weight per eligible action; only exact observed labels; missing/censored/disputed excluded from point-error metrics, retained in coverage".into(),
            "fitting only on training, mature labels; no IDs/scenario/seed/policy or outcome predictors; no rolling aggregates".into(),
            "source boundaries inclusive; synthetic logical seconds have no civil epoch; binary64 roundtrip, IDs lossless u64".into(),
            "signed residual=label-prediction; zero valid; MAPE deferred; quantiles nearest-rank p50/p95/p99; median midpoint; uncertainty unavailable without defensible independent groups".into()],
        metrics: vec!["MAE seconds (primary)", "RMSE seconds", "mean/median signed residual seconds", "absolute-error and positive-residual nearest-rank p50/p95/p99", "underprediction frequency=count(residual>0)/eligible exact actions; severity=mean positive residual, unavailable if none", "exact prediction/label coverage by cohort/group/distance band/source/policy"].into_iter().map(str::to_owned).collect(),
        synthetic: splits.evaluation.clone(), physical: EvaluationAvailability::EvaluationUnavailable("NoPhysicalDepartureOrArrivalMeasurements".into()),
    }
}

/// Rebuilds the dataset from retained sources and compares every derived component.
/// # Errors
/// Rejects corrupted source, altered features/labels/quality/splits or missing reproduction bytes.
pub fn verify_dataset(bundle: &DatasetBundle) -> Result<(), DatasetError> {
    let rebuilt = build_dataset(
        bundle.sources.clone(),
        &bundle.dataset_version,
        bundle.reproduction.clone(),
        bundle.splits.request.clone(),
    )?;
    if canonical(bundle)? != canonical(&rebuilt)? {
        return Err(DatasetError::Integrity(
            "derived dataset differs from retained evidence".into(),
        ));
    }
    Ok(())
}
/// Writes a new immutable directory via staging+rename; existing versions are never overwritten.
/// # Errors
/// Rejects existing destination, validation failures and filesystem errors.
pub fn publish_dataset(
    bundle: &DatasetBundle,
    destination: &Path,
) -> Result<PublicationManifest, DatasetError> {
    verify_dataset(bundle)?;
    let parent = destination.parent().unwrap_or_else(|| Path::new("."));
    std::fs::create_dir_all(parent)?;
    if destination.exists() {
        return Err(DatasetError::Integrity(
            "immutable dataset destination already exists".into(),
        ));
    }
    let stage = parent.join(format!(
        ".eta-stage-{}-{}",
        std::process::id(),
        digest(&canonical(bundle)?)
    ));
    std::fs::create_dir(&stage)?;
    let result = (|| {
        let bytes = serde_json::to_vec_pretty(bundle)?;
        let manifest = PublicationManifest {
            schema: "eta-publication/v1".into(),
            semantic_sha256: digest(&canonical(bundle)?),
            packaging_sha256: digest(&bytes),
            bundle_file: "bundle.json".into(),
        };
        write_sync(&stage.join("bundle.json"), &bytes)?;
        write_sync(
            &stage.join("manifest.json"),
            &serde_json::to_vec_pretty(&manifest)?,
        )?;
        std::fs::File::open(&stage)?.sync_all()?;
        std::fs::rename(&stage, destination)?;
        std::fs::File::open(parent)?.sync_all()?;
        Ok(manifest)
    })();
    if result.is_err() {
        let _ = std::fs::remove_dir_all(&stage);
    }
    result
}
fn write_sync(path: &Path, bytes: &[u8]) -> Result<(), DatasetError> {
    use std::io::Write;
    let mut file = std::fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(path)?;
    file.write_all(bytes)?;
    file.sync_all()?;
    Ok(())
}
/// Loads and verifies both packaging and semantic identities, then independently rebuilds.
/// # Errors
/// Rejects malformed manifests, corrupt bytes, source replay or derived content mismatch.
pub fn load_dataset(path: &Path) -> Result<DatasetBundle, DatasetError> {
    let manifest: PublicationManifest =
        serde_json::from_slice(&std::fs::read(path.join("manifest.json"))?)?;
    if manifest.schema != "eta-publication/v1" || manifest.bundle_file != "bundle.json" {
        return Err(DatasetError::Integrity("publication schema/path".into()));
    }
    let bytes = std::fs::read(path.join("bundle.json"))?;
    if digest(&bytes) != manifest.packaging_sha256 {
        return Err(DatasetError::Integrity("packaging digest".into()));
    }
    let bundle: DatasetBundle = serde_json::from_slice(&bytes)?;
    if digest(&canonical(&bundle)?) != manifest.semantic_sha256 {
        return Err(DatasetError::Integrity("semantic digest".into()));
    }
    verify_dataset(&bundle)?;
    Ok(bundle)
}

crates/roadrunner-dataset/src/features.r.utf8:
//! Constrained historical input boundary: no scenario, label, schedule or final-state access.
use crate::DatasetError;
use roadrunner_core::{
    geo::{Coordinate, Meters, Seconds},
    graph::FrozenGraph,
};
use roadrunner_dispatch::{FrozenExecutionLeg, OperationalRevision};
use roadrunner_simulation::StartedAction;
use serde::{Deserialize, Serialize};

/// Missingness distinguishes predictor absence, archival loss and unsupported semantics.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum UnavailableReason {
    /// Input did not exist at the predictor boundary.
    PredictorTimeAbsent,
    /// Original input existed but recoverable bytes were not retained.
    ArchivalLoss,
    /// Original schema/interpretation does not establish this field.
    UnsupportedSemantics,
    /// Not meaningful for this source (e.g. civil calendar for run seconds).
    NotApplicable,
}
/// A value or an explicit unavailability reason; missingness is metadata, not a predictor.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Availability<T> {
    /// Established by the recorded start inputs.
    Available(T),
    /// No fabricated/backfilled value.
    Unavailable(UnavailableReason),
}
/// Explicit historical availability witness; later archival time cannot substitute it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct AvailabilityWitness {
    /// Start commit order, authoritative even when timestamps round equally.
    pub start_revision: OperationalRevision,
    /// Original input captured synchronously inside the successful start operation.
    pub rule: String,
    /// Transform/interpretation version.
    pub transform: String,
}
/// Initial allowlisted values; no identity, seed, policy or latent future predictors.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct StartFeatures {
    /// Original route elapsed estimate in seconds, never rescheduled ETA.
    pub b0_seconds: Seconds,
    /// Original directed route length in meters.
    pub distance_meters: Meters,
    /// Origin location from original graph; archival loss is explicit.
    pub origin: Availability<Coordinate>,
    /// Destination location from original graph.
    pub destination: Availability<Coordinate>,
    /// Per-traversal original static multipliers, matched to original route edges.
    pub traffic_multipliers: Vec<f64>,
    /// Original per-traversal free-flow seconds where supported.
    pub edge_free_flow_seconds: Availability<Vec<Seconds>>,
    /// Core graph does not retain a road-class taxonomy in its current artifact.
    pub road_class: Availability<Vec<String>>,
    /// Simulation seconds have no civil timezone/epoch.
    pub day_of_week: Availability<u8>,
    /// Original complete route and graph/profile/traffic binding (lineage, not predictor IDs).
    pub original_route: FrozenExecutionLeg,
    /// Feature-category availability proof.
    pub witness: AvailabilityWitness,
}
/// Builds from original start inputs only; outcome and generator information is absent by type.
/// # Errors
/// Rejects graph/traffic mismatches and invalid path interpretation; never recomputes B0.
pub fn extract_features(
    start: &StartedAction,
    graph: Option<&FrozenGraph>,
) -> Result<StartFeatures, DatasetError> {
    let route = &start.original.route;
    if start.original.generation.value() != 0 {
        return Err(DatasetError::Source("not an original start".into()));
    }
    let (origin, destination, free_flow) = if let Some(g) = graph {
        if route.routing.graph_digest != g.metadata().snapshot_digest() {
            return Err(DatasetError::Integrity(
                "original graph/traffic identity".into(),
            ));
        }
        let overlay = roadrunner_core::cost::TrafficSnapshot::new(
            g,
            start
                .traffic
                .iter()
                .map(|o| (roadrunner_core::graph::EdgeId::new(o.edge_id), o.multiplier)),
        )
        .map_err(|e| DatasetError::Integrity(e.to_string()))?;
        if route.routing.traffic
            != roadrunner_dispatch::TrafficIdentity::Static(
                overlay.traffic_snapshot_digest().to_owned(),
            )
        {
            return Err(DatasetError::Integrity(
                "original traffic content identity".into(),
            ));
        }
        let node = |id| {
            g.node(id)
                .map(|n| Availability::Available(n.coordinate()))
                .ok_or_else(|| DatasetError::Integrity("route node absent".into()))
        };
        if route.nodes.len() != route.edges.len() + 1 {
            return Err(DatasetError::Integrity("route shape".into()));
        }
        let mut seconds = Vec::new();
        for (edge, pair) in route.edges.iter().zip(route.nodes.windows(2)) {
            let e = g
                .edge(*edge)
                .ok_or_else(|| DatasetError::Integrity("edge absent".into()))?;
            if e.from() != pair[0] || e.to() != pair[1] {
                return Err(DatasetError::Integrity("directed edge mismatch".into()));
            }
            seconds.push(e.free_flow_travel_time());
        }
        (
            node(route.from)?,
            node(route.to)?,
            Availability::Available(seconds),
        )
    } else {
        (
            Availability::Unavailable(UnavailableReason::ArchivalLoss),
            Availability::Unavailable(UnavailableReason::ArchivalLoss),
            Availability::Unavailable(UnavailableReason::ArchivalLoss),
        )
    };
    Ok(StartFeatures {
        b0_seconds: route.travel,
        distance_meters: route.distance,
        origin,
        destination,
        traffic_multipliers: route
            .edges
            .iter()
            .map(|id| {
                start
                    .traffic
                    .iter()
                    .find(|o| o.edge_id == id.value())
                    .map_or(1.0, |o| o.multiplier.value())
            })
            .collect(),
        edge_free_flow_seconds: free_flow,
        road_class: Availability::Unavailable(UnavailableReason::UnsupportedSemantics),
        day_of_week: Availability::Unavailable(UnavailableReason::NotApplicable),
        original_route: route.clone(),
        witness: AvailabilityWitness {
            start_revision: start.committed_revision,
            rule: "original-static-inputs-captured-at-start-commit/v1".into(),
            transform: "allowlist-route-static/v1".into(),
        },
    })
}

crates/roadrunner-dataset/src/labels.rs.utf8:
//! Evidence-qualified endpoint subtraction, independent of fulfillment success.
use roadrunner_core::geo::Seconds;
use roadrunner_dispatch::DispatchInstant;
use serde::{Deserialize, Serialize};

/// Producer identity does not imply measurement validity.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ProducerOrigin {
    /// Deterministic simulation driver.
    Simulator,
    /// External report source.
    ExternalReporter,
    /// Explicit controlled test.
    ControlledTest,
    /// Manual adapter.
    ManualIntegration,
    /// Historical origin not established.
    Unknown,
}
/// Scientific support independent of operational acceptance.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum MeasurementSupport {
    /// Deterministic synthetic clock and event coverage.
    SyntheticControlled,
    /// Clock-supported operational reports, not physical departure.
    OperationalReportInterval,
    /// Independently supported physical endpoints (not produced by this extractor).
    PhysicalMeasurementSupported,
    /// Missing historical measurement evidence.
    InsufficientEvidence,
}
/// Meaning of a value independently of its producer.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum RecordMeaning {
    /// Source assertion.
    Report,
    /// Authoritative accepted domain transition.
    CommittedDomainFact,
    /// Deterministic route output.
    RoutingEstimate,
    /// Derived value with versioned parent references.
    DerivedValue,
}
/// Four independent provenance dimensions, attached per relevant value category.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Provenance {
    /// Origin, never inferred from a source's name.
    pub producer_origin: ProducerOrigin,
    /// Record semantics.
    pub record_meaning: RecordMeaning,
    /// Evidence-qualified scientific cohort.
    pub measurement_support: MeasurementSupport,
    /// Recoverable source references and transform version.
    pub derivation_lineage: Vec<String>,
}
/// Exactly one primary state per committed start; reasons remain separate.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub enum Lifecycle {
    /// An accepted endpoint exists; exact-label eligibility is separately assessed.
    Observed,
    /// Source interval is still open; no supported non-arrival coverage.
    Pending,
    /// Explicit compatible observation coverage proves non-arrival through a bound.
    RightCensored,
    /// Closed source lacks sufficient endpoint/non-arrival evidence.
    MissingArrival,
    /// Conflicting evidence, invalid interval or credible dispute.
    DisputedOrInvalid,
}
/// Endpoint subtraction witness. No operational/physical clock conversion is implemented.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ClockWitness {
    /// Same deterministic run-relative f64 seconds; no epoch/timezone, drift or restart.
    SyntheticLogicalV1,
    /// Relationship, uncertainty or physical departure not established.
    Unsupported,
}
/// Inputs to lifecycle assessment; not accessible to feature construction.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct LabelEvidence {
    /// Logical start sampled at successful transition, not physical departure/COMMIT.
    pub start_effective_at: DispatchInstant,
    /// Original accepted source occurrence, never a rejected correction.
    pub arrival_reported_at: Option<DispatchInstant>,
    /// Source processing sample, not HTTP ingress.
    pub arrival_processing_sample_at: Option<DispatchInstant>,
    /// Inclusive extraction boundary.
    pub boundary: DispatchInstant,
    /// Explicit compatible non-arrival coverage bound; silence alone is insufficient.
    pub non_arrival_through: Option<DispatchInstant>,
    /// Whether observation collection is closed at this boundary.
    pub source_closed: bool,
    /// Credible evidence dispute under the immutable-as-of/v1 policy.
    pub disputed: bool,
    /// Endpoint/clock relationship evidence.
    pub clock: ClockWitness,
    /// Scientific support independent of lifecycle state.
    pub measurement: MeasurementSupport,
}
/// Immutable as-of label, with exact value and censor bound kept separate.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct LabelAssessment {
    /// One mutually exclusive primary partition.
    pub outcome: Lifecycle,
    /// Exact whole-leg duration, never an edge decomposition or missingness sentinel.
    pub duration_seconds: Option<Seconds>,
    /// Supported lower bound only; never enters exact metrics.
    pub lower_bound_seconds: Option<Seconds>,
    /// Overlapping reasons why exact evaluation is unavailable.
    pub reasons: Vec<String>,
    /// Original endpoint, boundary and clock evidence.
    pub evidence: LabelEvidence,
}
/// Assesses retained endpoint evidence without inventing clock compatibility.
#[must_use]
pub fn assess_label(e: LabelEvidence) -> LabelAssessment {
    let compatible = e.clock == ClockWitness::SyntheticLogicalV1
        && e.measurement == MeasurementSupport::SyntheticControlled;
    let mut reasons = Vec::new();
    if !compatible {
        reasons.push("UnsupportedClockOrMeasurement".into());
    }
    let arrival = e
        .arrival_reported_at
        .zip(e.arrival_processing_sample_at)
        .filter(|(_, processed)| *processed <= e.boundary);
    let mut exact = None;
    let mut bound = None;
    let outcome = if e.disputed {
        reasons.push("CredibleDispute".into());
        Lifecycle::DisputedOrInvalid
    } else if let Some((at, processed)) = arrival {
        if at < e.start_effective_at || at > processed || e.start_effective_at > e.boundary {
            reasons.push("InvalidEndpointOrdering".into());
            Lifecycle::DisputedOrInvalid
        } else {
            if compatible {
                exact = at.duration_since(e.start_effective_at).ok();
            }
            Lifecycle::Observed
        }
    } else if compatible
        && e.source_closed
        && e.non_arrival_through
            .is_some_and(|at| at >= e.start_effective_at && at <= e.boundary)
    {
        bound = e
            .non_arrival_through
            .and_then(|at| at.duration_since(e.start_effective_at).ok());
        reasons.push("NoExactArrival".into());
        Lifecycle::RightCensored
    } else if e.source_closed {
        reasons.push("NoAdmissibleArrivalOrCoverage".into());
        Lifecycle::MissingArrival
    } else {
        reasons.push("OpenObservationInterval".into());
        Lifecycle::Pending
    };
    LabelAssessment {
        outcome,
        duration_seconds: exact,
        lower_bound_seconds: bound,
        reasons,
        evidence: e,
    }
}

