//! Deterministic Phase 14 comparisons with fixed exogenous readiness events.

#[path = "support/preparation_scenario.rs"]
mod scenario;

use scenario::{Scenario, ScenarioResult, run};

fn main() -> ScenarioResult<()> {
    let mut comparisons = Vec::new();
    for (name, ready_after_seconds, actual_after_seconds) in [
        ("long-preparation", 1080.0, 1080.0),
        ("already-ready", 0.0, 0.0),
        ("underestimated-preparation", 1080.0, 1500.0),
    ] {
        let scenario = Scenario::new(ready_after_seconds)?;
        let ready_at = scenario
            .at
            .checked_add(roadrunner_core::geo::Seconds::new(actual_after_seconds)?)?;
        let baseline = run(&scenario, false, ready_at)?;
        let preparation = run(&scenario, true, ready_at)?;
        assert_eq!(baseline.observed.rider, scenario.near);
        if ready_after_seconds > 0.0 {
            assert_eq!(preparation.observed.rider, scenario.far);
            assert!(preparation.observed.waiting < baseline.observed.waiting);
            assert_eq!(
                preparation.observed.delivery_completed_at,
                baseline.observed.delivery_completed_at
            );
        } else {
            assert_eq!(preparation.observed.rider, scenario.near);
        }
        comparisons.push(serde_json::json!({
            "scenario": name,
            "actual_ready_at": ready_at,
            "baseline": baseline,
            "preparation_aware": preparation,
        }));
    }
    println!("{}", serde_json::to_string_pretty(&comparisons)?);
    Ok(())
}

crates/roadrunner-dispatch/examples/supp.utf8:
//! Shared synthetic fixture for the example and Phase 14 correctness tests.

use std::error::Error;

use roadrunner_core::geo::{CanonicalCoordinate, KilometersPerHour, Seconds, haversine_distance};
use roadrunner_core::graph::{
    AccessClass, BuilderNodeId, BuilderSegmentId, EdgeProperties, FrozenGraph, GraphBuildIdentity,
    GraphBuilder, GraphMetadata, GraphSnapshotId, NodeId,
};
use roadrunner_dispatch::{
    AssignmentDecision, Availability, CandidatePolicy, CapacityUnits, CoreRouteProvider,
    DecisionId, DispatchDecisionOutcome, DispatchInstant, DispatchSnapshot, FulfillmentState,
    Order, OrderId, OrderReadiness, PreparationAwareStrategy, RiderId, RiderPlan, RiderProfile,
    RiderState, RouteOutcome, RouteProvider, RoutingAnchor, RoutingAnchors, RoutingEpoch,
    TrafficContext, World, WorldData, basic_dispatch, onboard_load, preparation_aware_dispatch,
    validate_world,
};
use serde::Serialize;

pub type ScenarioResult<T> = Result<T, Box<dyn Error>>;

pub struct Scenario {
    pub graph: FrozenGraph,
    pub data: WorldData,
    pub anchors: RoutingAnchors,
    pub at: DispatchInstant,
    pub epoch: RoutingEpoch,
    pub order: OrderId,
    pub near: RiderId,
    pub far: RiderId,
}

fn example_graph() -> ScenarioResult<FrozenGraph> {
    let mut builder = GraphBuilder::new(
        GraphSnapshotId::new(14),
        GraphMetadata::new(
            "dispatch-motorcycle/v1",
            "synthetic preparation scenario",
            GraphBuildIdentity::new("phase14-scenario", "v1", "v1", "synthetic"),
        ),
    );
    let points = [
        CanonicalCoordinate::new(0, 0)?,
        CanonicalCoordinate::new(0, 10_000)?,
        CanonicalCoordinate::new(0, 30_000)?,
        CanonicalCoordinate::new(0, 40_000)?,
        CanonicalCoordinate::new(0, 50_000)?,
    ];
    for (id, point) in (0_u64..).zip(points) {
        builder.add_node(BuilderNodeId::new(id), point)?;
    }
    // Controlled free-flow travel: near → pickup 5m; far → pickup 15m; delivery 10m.
    for (id, from, to, duration) in [
        (0, 1_usize, 0_usize, 300.0),
        (1, 2, 0, 900.0),
        (2, 0, 3, 600.0),
    ] {
        let distance = haversine_distance(points[from].to_coordinate(), points[to].to_coordinate());
        builder.add_segment(
            BuilderSegmentId::new(id),
            BuilderNodeId::new(u64::try_from(from)?),
            BuilderNodeId::new(u64::try_from(to)?),
            vec![points[from], points[to]],
            Some(EdgeProperties::new(
                KilometersPerHour::new(distance.value() / duration * 3.6)?,
                None,
                AccessClass::General,
            )),
            None,
        )?;
    }
    Ok(builder.finalize()?)
}

impl Scenario {
    pub fn new(ready_after_seconds: f64) -> ScenarioResult<Self> {
        let graph = example_graph()?;
        let order = OrderId::new(1);
        let near = RiderId::new(1);
        let far = RiderId::new(2);
        let at = DispatchInstant::new(10_000.0)?;
        let epoch = RoutingEpoch(at);
        let anchor = |node| -> ScenarioResult<RoutingAnchor> {
            Ok(RoutingAnchor {
                coordinate: graph
                    .node(NodeId::new(node))
                    .ok_or("missing node")?
                    .coordinate(),
                graph_digest: graph.metadata().snapshot_digest().to_owned(),
                node: NodeId::new(node),
            })
        };
        let pickup = anchor(0)?;
        let dropoff = anchor(3)?;
        let mut data = WorldData::default();
        data.orders.insert(
            order,
            Order {
                id: order,
                pickup: pickup.coordinate,
                dropoff: dropoff.coordinate,
                created_at: at,
                deadline: None,
                demand: CapacityUnits::new(1),
            },
        );
        data.readiness.insert(
            order,
            OrderReadiness {
                expected_at: Some(at.checked_add(Seconds::new(ready_after_seconds)?)?),
                observed_at: None,
            },
        );
        data.fulfillment
            .insert(order, FulfillmentState::AwaitingPickup);
        let mut anchors = RoutingAnchors::default();
        anchors.pickups.insert(order, pickup);
        anchors.dropoffs.insert(order, dropoff);
        for (rider, node) in [(near, 1), (far, 2)] {
            let origin = anchor(node)?;
            data.profiles.insert(
                rider,
                RiderProfile {
                    id: rider,
                    routing_profile: graph.metadata().routing_profile().to_owned(),
                    max_capacity: CapacityUnits::new(1),
                },
            );
            data.riders.insert(
                rider,
                RiderState {
                    coordinate: origin.coordinate,
                    availability: Availability::Available,
                },
            );
            data.plans.insert(rider, RiderPlan::default());
            anchors.riders.insert(rider, origin);
        }
        Ok(Self {
            graph,
            data,
            anchors,
            at,
            epoch,
            order,
            near,
            far,
        })
    }

    pub fn world(&self) -> ScenarioResult<World> {
        Ok(World::new(14, self.data.clone())?)
    }
}

#[derive(Debug, Serialize)]
pub struct ObservedMetrics {
    pub rider: RiderId,
    pub pickup_arrival: DispatchInstant,
    pub pickup_completed_at: DispatchInstant,
    pub delivery_completed_at: DispatchInstant,
    pub waiting: Seconds,
    pub delivery_travel: Seconds,
    pub completion_time: Seconds,
}

#[derive(Debug, Serialize)]
pub struct ScenarioRun {
    pub decision: AssignmentDecision,
    pub observed: ObservedMetrics,
    pub final_fulfillment: FulfillmentState,
}

/// Each strategy starts from a fresh equivalent world and identical exogenous ready event.
/// The Phase 13 baseline may underestimate completion; execution obeys actual readiness.
pub fn run(
    scenario: &Scenario,
    preparation_aware: bool,
    actual_ready_at: DispatchInstant,
) -> ScenarioResult<ScenarioRun> {
    let mut world = scenario.world()?;
    let provider = CoreRouteProvider::new(&scenario.graph, TrafficContext::FreeFlow)?;
    let snapshot = DispatchSnapshot::new(
        &world,
        scenario.at,
        scenario.epoch,
        &provider,
        &scenario.anchors,
    )?;
    let decision = if preparation_aware {
        preparation_aware_dispatch(
            &snapshot,
            scenario.order,
            DecisionId::new(14),
            CandidatePolicy::Exhaustive,
            PreparationAwareStrategy::default(),
        )?
    } else {
        basic_dispatch(
            &snapshot,
            scenario.order,
            DecisionId::new(13),
            CandidatePolicy::Exhaustive,
        )?
    };
    let DispatchDecisionOutcome::Assigned(proposal) = decision.outcome() else {
        return Err("expected assigned scenario".into());
    };
    let rider = proposal.rider;
    // Execute both road legs against the fixed graph rather than reporting predictions.
    let RouteOutcome::RouteFound(first) = provider.route(
        scenario.anchors.riders[&rider].node,
        scenario.anchors.pickups[&scenario.order].node,
        scenario.epoch.departure_seconds(scenario.at)?,
    )?
    else {
        return Err("expected execution pickup route".into());
    };
    let arrival = scenario.at.checked_add(first.route.elapsed_travel_time())?;
    let pickup_completed_at = if arrival > actual_ready_at {
        arrival
    } else {
        actual_ready_at
    };
    world.commit(&decision)?;
    world.observe_ready(scenario.order, actual_ready_at)?;
    world.pickup(rider, scenario.order, pickup_completed_at)?;
    let RouteOutcome::RouteFound(leg) = provider.route(
        scenario.anchors.pickups[&scenario.order].node,
        scenario.anchors.dropoffs[&scenario.order].node,
        scenario.epoch.departure_seconds(pickup_completed_at)?,
    )?
    else {
        return Err("expected execution road route".into());
    };
    let delivery_completed_at = pickup_completed_at.checked_add(leg.route.elapsed_travel_time())?;
    world.deliver(rider, scenario.order, delivery_completed_at)?;
    validate_world(world.data())?;
    assert_eq!(world.data().plans[&rider], RiderPlan::default());
    assert!(world.data().assignments.is_empty());
    assert_eq!(onboard_load(world.data(), rider)?, CapacityUnits::new(0));
    let final_fulfillment = world.data().fulfillment[&scenario.order];
    let FulfillmentState::Delivered {
        at, picked_up_at, ..
    } = final_fulfillment
    else {
        return Err("expected completed delivery".into());
    };
    let observed = ObservedMetrics {
        rider,
        pickup_arrival: arrival,
        pickup_completed_at: picked_up_at,
        delivery_completed_at: at,
        waiting: picked_up_at.duration_since(arrival)?,
        delivery_travel: at.duration_since(picked_up_at)?,
        completion_time: at.duration_since(scenario.at)?,
    };
    Ok(ScenarioRun {
        decision,
        observed,
        final_fulfillment,
    })
}

crates/roadrunner-dispatch/src/checkpoin.utf8:
//! Independently versioned storage reconstruction; never a public writable state clone.
use super::{
    ActionId, ActiveExecution, AdoptedContext, AppliedEffect, AppliedExecutionEffectId,
    OperationalRevision, OperationalState, OperationalTransitionRecord, PlanRevision, RiderId,
};
use crate::{CommitError, DispatchInstant, PublicationProvenance, World, WorldData, WorldVersion};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

/// Corrupt, unsupported or inconsistent durable authority. Restoration fails closed.
#[derive(Debug, thiserror::Error)]
pub enum CheckpointError {
    /// Malformed versioned record.
    #[error("invalid operational checkpoint: {0}")]
    Encoding(#[from] serde_json::Error),
    /// Schema, digest, compatibility mode, history or allocators are invalid.
    #[error("unsupported or corrupt operational checkpoint")]
    Invalid,
    /// Domain/active execution invariants reject restoration.
    #[error(transparent)]
    Domain(#[from] CommitError),
}
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct StoredWorld {
    identity: u64,
    version: WorldVersion,
    data: WorldData,
}
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct StoredState {
    world: StoredWorld,
    revision: OperationalRevision,
    plans: BTreeMap<RiderId, PlanRevision>,
    execution: BTreeMap<RiderId, ActiveExecution>,
    contexts: BTreeMap<String, AdoptedContext>,
    effects: BTreeMap<AppliedExecutionEffectId, AppliedEffect>,
    next_action: ActionId,
    next_attempt: u64,
    next_effect: AppliedExecutionEffectId,
    next_order: u64,
    next_rider: u64,
    recovery_at: Option<DispatchInstant>,
    history: Vec<OperationalTransitionRecord>,
    publications: Vec<PublicationProvenance>,
}
impl OperationalState {
    /// Exports the complete version-1 durable storage value, including allocators,
    /// recognition, frozen work and immutable publication/history evidence.
    /// This is a trusted storage format, never an HTTP input or an event replay.
    /// # Errors
    /// Rejects compatibility/simulation authority or invalid state.
    pub fn checkpoint(&self) -> Result<serde_json::Value, CheckpointError> {
        if self.compatibility {
            return Err(CheckpointError::Invalid);
        }
        self.validate()?;
        let state = StoredState {
            world: StoredWorld {
                identity: self.world.identity(),
                version: self.world.version(),
                data: self.data().clone(),
            },
            revision: self.revision,
            plans: self.plans.clone(),
            execution: self.execution.clone(),
            contexts: self.contexts.clone(),
            effects: self.effects.clone(),
            next_action: self.next_action,
            next_attempt: self.next_attempt,
            next_effect: self.next_effect,
            next_order: self.next_order,
            next_rider: self.next_rider,
            recovery_at: self.recovery_at,
            history: self.history.clone(),
            publications: self.publications.clone(),
        };
        let payload = serde_json::to_value(state)?;
        Ok(
            serde_json::json!({"schema_version":1,"semantics":"roadrunner.operational-storage/v1","state":payload}),
        )
    }
    /// Restores a complete storage record and validates domain, execution, counter
    /// and history invariants before exposing an operational authority.
    /// The storage adapter separately verifies transaction/fence/content integrity.
    /// # Errors
    /// Rejects unknown schema/semantics, corrupt state or allocator reuse.
    pub fn restore_checkpoint(record: &serde_json::Value) -> Result<Self, CheckpointError> {
        if record["schema_version"] != 1
            || record["semantics"] != "roadrunner.operational-storage/v1"
        {
            return Err(CheckpointError::Invalid);
        }
        let s: StoredState = serde_json::from_value(record["state"].clone())?;
        let state = Self {
            world: World::restore(s.world.identity, s.world.version, s.world.data)?,
            compatibility: false,
            revision: s.revision,
            plans: s.plans,
            execution: s.execution,
            contexts: s.contexts,
            effects: s.effects,
            next_action: s.next_action,
            next_attempt: s.next_attempt,
            next_effect: s.next_effect,
            next_order: s.next_order,
            next_rider: s.next_rider,
            recovery_at: s.recovery_at,
            history: s.history,
            publications: s.publications,
        };
        state.validate()?;
        let data = state.data();
        if data.orders.keys().any(|id| id.value() >= state.next_order)
            || data
                .profiles
                .keys()
                .any(|id| id.value() >= state.next_rider)
            || state.plans.keys().ne(data.profiles.keys())
            || state
                .execution
                .values()
                .any(|a| a.action_id >= state.next_action || a.id >= state.next_attempt)
            || state.effects.iter().any(|(id, e)| {
                *id != e.id || *id >= state.next_effect || e.action >= state.next_action
            })
            || state.contexts.iter().any(|(name, c)| {
                name != &c.identity.category
                    || c.identity.content.is_empty()
                    || c.revision.value() == 0
            })
        {
            return Err(CheckpointError::Invalid);
        }
        let mut revision = 0;
        for h in &state.history {
            if h.before.namespace != state.revision.namespace
                || h.after.namespace != state.revision.namespace
                || h.before.number != revision
                || h.after.number != revision.checked_add(1).ok_or(CheckpointError::Invalid)?
            {
                return Err(CheckpointError::Invalid);
            }
            revision = h.after.number;
        }
        if revision != state.revision.number
            || state.publications.iter().any(|p| {
                p.schema_version != 1
                    || p.validity_policy != crate::STATIC_MONOTONE_POLICY
                    || p.committed_revision.namespace != state.revision.namespace
                    || p.committed_revision.number > state.revision.number
                    || p.committed_at > p.valid_until
                    || p.committed_at < p.evaluated_at
            })
        {
            return Err(CheckpointError::Invalid);
        }
        Ok(state)
    }
    /// Stamps staged new acceptance and publication records with the storage gate
    /// clock sample. The original reference/policy and existing acceptance stay fixed.
    /// Must run under the storage namespace lock before durable publication.
    /// # Errors
    /// Rejects changed namespace, time regression or certificate/reference expiry.
    pub fn stamp_storage_commit(
        &mut self,
        previous: &Self,
        at: DispatchInstant,
    ) -> Result<(), CheckpointError> {
        if self.revision.namespace != previous.revision.namespace
            || self.publications.len() < previous.publications.len()
        {
            return Err(CheckpointError::Invalid);
        }
        if self.world.identity() != previous.world.identity()
            || !self.history.starts_with(&previous.history)
            || !self.publications.starts_with(&previous.publications)
            || previous
                .data()
                .accepted
                .iter()
                .any(|(id, terms)| self.data().accepted.get(id) != Some(terms))
        {
            return Err(CheckpointError::Invalid);
        }
        if self.publications.len() == previous.publications.len()
            && self.data().accepted.len() != previous.data().accepted.len()
        {
            return Err(CheckpointError::Invalid);
        }
        for p in &self.publications[previous.publications.len()..] {
            if p.source != previous.revision || at < p.committed_at || at > p.valid_until {
                return Err(CheckpointError::Invalid);
            }
        }
        self.world.stamp_new_acceptance(previous.data(), at)?;
        if self.recovery_at != previous.recovery_at && self.recovery_at.is_some() {
            self.recovery_at = Some(at);
        }
        let payload = serde_json::json!({"world":self.data(),"execution":self.execution(),"plan_revisions":self.plan_revisions(),"recovery_at":self.recovery_at()});
        for p in &mut self.publications[previous.publications.len()..] {
            p.committed_at = at;
            p.commitment_record.committed_at = Some(at);
            p.decision_record.committed_at = Some(at);
            p.commitment_record.payload = payload.clone();
        }
        self.validate()?;
        Ok(())
    }
}

crates/roadrunner-dispatch/src/decision..utf8:
use roadrunner_core::geo::{Meters, Seconds};
use serde::Serialize;

use crate::{
    CommittedAssignment, DecisionId, DispatchInstant, OrderId, PlanEvaluation, PlanValidityError,
    PreparationPolicyEvidence, PreparationScoreContributions, RiderId, RiderPlan, RoutingEpoch,
    RoutingProvenance, WorldVersion,
};

/// Candidate-generation policy with recorded configuration.
#[derive(Debug, Clone, Copy, PartialEq, Serialize)]
pub enum CandidatePolicy {
    /// Evaluate all riders passing Basic Dispatch eligibility.
    Exhaustive,
    /// Evaluate a spatial radius/limit shortlist of eligible positions.
    Spatial {
        /// Inclusive straight-line radius.
        radius: Meters,
        /// Maximum number of candidates; zero produces an empty shortlist.
        limit: usize,
    },
}

/// Whether candidate generation covers the complete eligible rider fleet.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum CandidateCoverage {
    /// Every eligible rider is evaluated.
    Complete,
    /// Bounded screening may exclude feasible or better riders.
    PotentiallyIncomplete,
}

impl CandidatePolicy {
    /// Coverage is a policy guarantee, never inferred from returned count.
    #[must_use]
    pub const fn coverage(self) -> CandidateCoverage {
        match self {
            Self::Exhaustive => CandidateCoverage::Complete,
            Self::Spatial { .. } => CandidateCoverage::PotentiallyIncomplete,
        }
    }
}

/// Typed structural rejection, never an infinite or penalized score.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub enum CandidateRejection {
    /// Valid anchored locations have no legal connecting road route.
    NoRoute,
    /// Demand cannot fit maximum scalar rider capacity.
    CapacityExceeded,
    /// Pending work violates state-aware plan validity.
    InvalidPlan,
    /// Proposed responsibility contradicts onboard custody.
    CustodyViolation,
    /// Rider cannot use the pinned routing profile.
    UnsupportedCandidateProfile,
}

impl From<PlanValidityError> for CandidateRejection {
    fn from(value: PlanValidityError) -> Self {
        match value {
            PlanValidityError::InvalidPlan => Self::InvalidPlan,
            PlanValidityError::CustodyViolation => Self::CustodyViolation,
            PlanValidityError::CapacityExceeded => Self::CapacityExceeded,
        }
    }
}

/// Shared dispatch deadline semantics; no lateness penalty or hard rejection.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum DeadlinePolicy {
    /// Observe completed-dropoff lateness without affecting ranking or feasibility.
    SoftObserved,
}

/// Structured objective contributions, with an optional preparation-aware breakdown.
#[derive(Debug, Clone, Copy, PartialEq, Serialize)]
pub struct ScoreContributions {
    /// Rider-to-pickup road movement.
    pub pickup_travel: Seconds,
    /// Pickup-to-dropoff road movement.
    pub delivery_travel: Seconds,
    /// Completion and idle penalty for preparation-aware scoring; absent for baseline.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub preparation: Option<PreparationScoreContributions>,
    /// Straight-line pickup distance used by nearest-rider ranking; absent otherwise.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub nearest_distance: Option<Meters>,
    /// Checked time objective in seconds; informational road travel for nearest ranking.
    pub total: Seconds,
}

/// Evidence for one evaluated candidate, ordered canonically by `RiderId`.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct CandidateEvidence {
    /// Rider considered.
    pub rider: RiderId,
    /// Metrics and score, or structural rejection.
    pub result: CandidateResult,
}

/// Feasible measured outcome is distinct from structural candidate rejection.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub enum CandidateResult {
    /// Feasible, fully evaluated remaining plan.
    Feasible {
        /// Timing and physical metrics, independent of strategy preference.
        evaluation: Box<PlanEvaluation>,
        /// Structured contributions for the recorded objective.
        score: ScoreContributions,
    },
    /// Structurally infeasible candidate.
    Rejected(CandidateRejection),
}

/// Exact responsibility and remaining-plan state change proposed by evaluation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct AssignmentProposal {
    /// New request.
    pub order: OrderId,
    /// Selected idle rider; derived convenience identity.
    pub rider: RiderId,
    /// Exact prior responsibility expected at commit.
    pub expected_assignment: Option<CommittedAssignment>,
    /// Exact prior remaining work expected at commit.
    pub expected_plan: RiderPlan,
    /// Proposed current responsibility.
    pub proposed_assignment: CommittedAssignment,
    /// Proposed complete remaining plan.
    pub proposed_plan: RiderPlan,
}

/// Scope of the completed infeasibility claim.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum UnassignedScope {
    /// No feasible rider among the complete Basic Dispatch eligible fleet.
    EligibleFleet,
    /// No feasible rider among the bounded candidates evaluated.
    EvaluatedCandidates,
}

/// Completed evaluation outcome; evaluation failures use a separate Result error.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub enum DispatchDecisionOutcome {
    /// Exact coherent state proposal, not a committed assignment.
    Assigned(AssignmentProposal),
    /// Valid completed decision without a feasible selected plan.
    Unassigned {
        /// Meaning of the unsuccessful candidate search.
        scope: UnassignedScope,
    },
}

/// Structured reason for deterministic selection.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub enum SelectionReason {
    /// Unique minimum strategy score among evaluated feasible candidates.
    LowestScore,
    /// Exact minimum score tie resolved by lower rider identity.
    ExactScoreThenRiderId {
        /// Canonical identities of all riders tied at the minimum.
        tied_riders: Vec<RiderId>,
    },
}

/// Compact replay/explanation evidence; full hypothetical road geometry is optional.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct DecisionEvidence {
    /// Caller-supplied immutable decision identity.
    pub decision_id: DecisionId,
    /// Source world identity.
    pub world_identity: u64,
    /// Whole-world source version.
    pub world_version: WorldVersion,
    /// Explicit caller-supplied evaluation instant.
    pub evaluated_at: DispatchInstant,
    /// Declared checked conversion epoch.
    pub routing_epoch: RoutingEpoch,
    /// Fixed graph, traffic, and profile.
    pub routing: RoutingProvenance,
    /// Versioned pure ranking policy; preparation configuration is recorded separately.
    pub strategy: String,
    /// Readiness inputs and waiting-penalty configuration; absent for Phase 13.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub preparation: Option<PreparationPolicyEvidence>,
    /// Versioned hard constraint policy.
    pub feasibility_policy: String,
    /// Versioned eligibility policy.
    pub eligibility_policy: String,
    /// Explicit baseline deadline semantics.
    pub deadline_policy: DeadlinePolicy,
    /// Candidate-generation policy/configuration.
    pub candidate_policy: CandidatePolicy,
    /// Complete or potentially incomplete coverage.
    pub coverage: CandidateCoverage,
    /// Canonical evidence for every evaluated candidate.
    pub candidates: Vec<CandidateEvidence>,
    /// Selection reason, absent for Unassigned.
    pub selection_reason: Option<SelectionReason>,
}

/// Immutable completed decision; only the evaluator can construct it.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct AssignmentDecision {
    evidence: DecisionEvidence,
    outcome: DispatchDecisionOutcome,
}

impl AssignmentDecision {
    pub(crate) const fn new(evidence: DecisionEvidence, outcome: DispatchDecisionOutcome) -> Self {
        Self { evidence, outcome }
    }
    /// Returns read-only structured evidence.
    #[must_use]
    pub const fn evidence(&self) -> &DecisionEvidence {
        &self.evidence
    }
    /// Returns the exact proposal or structured unsuccessful outcome.
    #[must_use]
    pub const fn outcome(&self) -> &DispatchDecisionOutcome {
        &self.outcome
    }
    /// Renders a concise explanation from structured source-of-truth evidence.
    #[must_use]
    pub fn explanation(&self) -> String {
        match &self.outcome {
            DispatchDecisionOutcome::Assigned(p) => {
                let objective = if self.evidence.strategy == "nearest-straight-line/v1" {
                    "straight-line pickup distance"
                } else if self.evidence.strategy == "lowest-pickup-eta/v1" {
                    "pickup road travel"
                } else if self.evidence.strategy == "lowest-completion-time/v1" {
                    "readiness-aware completion time"
                } else if self.evidence.preparation.is_some() {
                    "completion time + rider waiting penalty"
                } else {
                    "pickup + delivery road travel"
                };
                format!(
                    "Rider {} has the lowest {objective} score among evaluated candidates ({:?} coverage)",
                    p.rider.value(),
                    self.evidence.coverage
                )
            }
            DispatchDecisionOutcome::Unassigned { scope } => {
                format!("No feasible rider in scope {scope:?}")
            }
        }
    }
}

