    /// Accepted completion of pickup/dropoff service.
    Completion,
}

/// Read-only recognized execution evidence; acceptance is not physical measurement.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AppliedEffect {
