fn hand_worked_all_intermediate_times_loads_and_colocated_independent_stops() {
    let fixture = Fixture::new();
    let world = ok(World::new(17, fixture.data.clone()));
    let mut inputs = fixture.inputs(&world, at(0.0));
    ok(inputs
        .policies
