            Stop::Dropoff(OrderId::new(1)),
        ],
    };
    // The independent evaluator accepts a provisional new assignment; existing A is committed input.
    let mut data = world.data().clone();
    data.assignments.insert(
        OrderId::new(1),
        CommittedAssignment {
            order: OrderId::new(1),
            rider: RiderId::new(1),
