    assert!(
        proposal
            .impacts
            .iter()
            .all(|i| i.consumed_seconds == Some(0.0))
    );
    ok(world.commit_recovery(&d, &ctx));
    assert_eq!(world.data().accepted, terms);
    // Both riders now project farther away; neither can erase the original reference.
    let r = RiderId::new(1);
