CREATE TABLE rr_event_heads(namespace text NOT NULL REFERENCES rr_worlds(namespace), actor text NOT NULL, revision bigint NOT NULL CHECK(revision>=0), fingerprint text NOT NULL, PRIMARY KEY(namespace,actor));
