    assert_eq!(restored, staged);
    assert_eq!(reopened.head().revision, 1);
    assert_eq!(
        db.query_one("SELECT count(*) FROM rr_outbox WHERE namespace=$1", &[&ns])
            .unwrap()
            .get::<_, i64>(0),
        1
    );
    drop(reopened);
    std::fs::remove_dir_all(directory).unwrap();
}

